class TrustEditor(tk.Tk):
    def __init__(self):
        super().__init__()
        self.title("Trust Editor")
        self.geometry("1100x800")
        self.style = ttk.Style()
        self.style.configure("Icon.TButton", padding=0)
        self.style.configure(
            "HelpHeader.TLabel",
            foreground="#2a7ae2",
            font=("TkDefaultFont", 10, "underline"),
        )

        self.trust_files = self.get_trust_files()
        self.current_trust = tk.StringVar()
        self.create_widgets()
        self.load_sql_data()
        self.current_trust.trace_add("write", self.on_trust_selected)

    def load_sql_data(self):
        self.ja_job_map = {}
        self.ws_job_map = {}

        # Paths
        base_dir = os.path.dirname(os.path.abspath(__file__))
        sql_dir = os.path.join(base_dir, "../../../../sql")

        # Load Abilities
        try:
            p = os.path.join(sql_dir, "abilities.sql")
            if os.path.exists(p):
                with open(p, "r", encoding="utf-8", errors="ignore") as f:
                    content = f.read()
                    matches = re.findall(
                        r"INSERT INTO `abilities` VALUES \((\d+),'([^']+)',(\d+),",
                        content,
                    )
                    for _, name, job_id in matches:
                        key = f"xi.ja.{name.upper()}"
                        self.ja_job_map[key] = int(job_id)
        except Exception as e:
            print(f"Error loading abilities.sql: {e}")

        # Load Weapon Skills
        try:
            p = os.path.join(sql_dir, "weapon_skills.sql")
            if os.path.exists(p):
                with open(p, "r", encoding="utf-8", errors="ignore") as f:
                    content = f.read()
                    matches = re.findall(
                        r"INSERT INTO `weapon_skills` VALUES \((\d+),'([^']+)',0x([0-9A-Fa-f]+),",
                        content,
                    )
                    for _, name, hex_str in matches:
                        key = f"xi.ws.{name.upper()}"
                        jobs = []
                        # Hex string is 2 chars per byte
                        for i in range(0, len(hex_str), 2):
                            if i // 2 >= 22:
                                break
                            byte_val = int(hex_str[i : i + 2], 16)
                            if byte_val > 0:
                                jobs.append((i // 2) + 1)
                        self.ws_job_map[key] = jobs
        except Exception as e:
            print(f"Error loading weapon_skills.sql: {e}")

        # Load Spells
        self.spell_type_map = {}
        try:
            p = os.path.join(sql_dir, "spells.sql")
            if os.path.exists(p):
                with open(p, "r", encoding="utf-8", errors="ignore") as f:
                    content = f.read()
                    # INSERT INTO `spells` VALUES (spellId, 'name', magicType, ...
                    # magicType is 3rd column
                    matches = re.findall(
                        r"INSERT INTO `spells` VALUES \((\d+),'([^']+)',(\d+),", content
                    )
                    for _, name, mtype in matches:
                        key = f"xi.magic.spell.{name.upper()}"
                        self.spell_type_map[key] = int(mtype)
        except Exception as e:
            print(f"Error loading spells.sql: {e}")

    def open_filter_list_dialog(
        self,
        values,
        target_var,
        title="Select Item",
        width=40,
        height=12,
        help_category=None,
        job_var=None,  # Added for job filtering
        filter_by_job=False,  # Added for job filtering
        filter_by_weapon=False,  # Added for weapon filtering
        selector_var=None,
        is_text_widget=False,  # If True, target_var is a Text widget instead of StringVar
    ):
        dialog = tk.Toplevel(self)
        dialog.title(title)
        dialog.geometry("500x500")

        # Make transient and modal-like
        dialog.transient(self)
        dialog.grab_set()

        # Position at mouse
        x = self.winfo_pointerx()
        y = self.winfo_pointery()
        dialog.geometry(f"+{x}+{y}")

        # Close on Escape
        dialog.bind("<Escape>", lambda e: dialog.destroy())

        # Dynamic filtering based on selector_var
        if selector_var:
            selector_val = selector_var.get()
            if selector_val == "Magic":
                # Filter for spells (xi.magic.spell.*)
                values = [v for v in values if "xi.magic.spell." in v]
            elif selector_val == "JobAbility":
                # Filter for JAs (xi.ja." in v or "xi.ability." in v)
                values = [v for v in values if "xi.ja." in v]
            elif selector_val == "WeaponSkill":
                # Filter for WSs (xi.ws.*)
                values = [v for v in values if "xi.ws." in v]
            # Add more specific filters if needed (e.g. Item -> items?)

        search_var = tk.StringVar()
        ttk.Label(dialog, text="Filter:").pack(anchor="w", padx=8, pady=(8, 2))
        search_entry = ttk.Entry(dialog, textvariable=search_var, width=width)
        search_entry.pack(fill=tk.X, padx=8)

        # Job Filter (Optional)
        # If filter_by_job is True, job_var will be passed in.
        # If not, we create a dummy one to avoid errors in refresh.
        # Job Filter (Optional)
        # If filter_by_job is True, job_var will be passed in.
        # If not, we create a dummy one to avoid errors in refresh.
        local_job_var = tk.StringVar(value=job_var.get() if job_var else "All")
        if filter_by_job:
            filter_frame = ttk.Frame(dialog)
            filter_frame.pack(fill=tk.X, padx=8, pady=(8, 0))
            ttk.Label(filter_frame, text="Job:").pack(side=tk.LEFT)
            jobs = ["All"] + sorted(list(JOB_TEMPLATES.keys()))
            job_combo = ttk.Combobox(
                filter_frame,
                textvariable=local_job_var,
                values=jobs,
                state="readonly",
                width=10,
            )
            job_combo.pack(side=tk.LEFT, padx=5)
            # Use the passed job_var if available, otherwise use local_job_var
            job_var = job_var if job_var else local_job_var

        # Weapon Filter (Optional)
        local_weapon_var = tk.StringVar(value="All")
        if filter_by_weapon:
            # If filter_frame doesn't exist yet (no job filter), create it
            if not filter_by_job:
                filter_frame = ttk.Frame(dialog)
                filter_frame.pack(fill=tk.X, padx=8, pady=(8, 0))

            ttk.Label(filter_frame, text="Weapon:").pack(side=tk.LEFT, padx=(10, 0))
            # Get list of combat skills (id 1-12, 25-26 usually)
            # Filter SKILLS to only include relevant weapon skills
            weapon_skills = [
                k for k, v in SKILLS.items() if (1 <= v <= 12) or (25 <= v <= 26)
            ]
            weapon_skills = ["All"] + sorted(weapon_skills)
            weapon_combo = ttk.Combobox(
                filter_frame,
                textvariable=local_weapon_var,
                values=weapon_skills,
                state="readonly",
                width=15,
            )
            weapon_combo.pack(side=tk.LEFT, padx=5)
            # Use local_weapon_var for filtering logic
        # Magic Type Filter (Optional)
        local_magic_type_var = tk.StringVar(value="All")
        if selector_var and selector_var.get() == "Magic":
            # If filter_frame doesn't exist yet, create it
            if not filter_by_job and not filter_by_weapon:
                filter_frame = ttk.Frame(dialog)
                filter_frame.pack(fill=tk.X, padx=8, pady=(8, 0))
            elif "filter_frame" not in locals():
                # It might have been created inside if blocks, but we need reference
                # Actually, if filter_by_job is True, filter_frame is created.
                # If not, we need to find it or create it.
                # Simplest way: check if we have a filter_frame variable in scope?
                # Python scoping is function-level, so if it was created in if block, it exists.
                # But if filter_by_job was False, it might not exist.
                pass

            # Ensure filter_frame exists
            if "filter_frame" not in locals():
                filter_frame = ttk.Frame(dialog)
                filter_frame.pack(fill=tk.X, padx=8, pady=(8, 0))

            ttk.Label(filter_frame, text="Type:").pack(side=tk.LEFT, padx=(10, 0))
            magic_types = [
                "All",
                "WhiteMagic",
                "BlackMagic",
                "Summoner",
                "Ninjutsu",
                "Bard",
                "BlueMagic",
                "Geomancy",
            ]
            magic_combo = ttk.Combobox(
                filter_frame,
                textvariable=local_magic_type_var,
                values=magic_types,
                state="readonly",
                width=12,
            )
            magic_combo.pack(side=tk.LEFT, padx=5)

            # Add trace to refresh
            local_magic_type_var.trace_add(
                "write", lambda *args: refresh(search_var.get())
            )

        list_frame = ttk.Frame(dialog)
        list_frame.pack(fill=tk.BOTH, expand=True, padx=8, pady=8)

        scrollbar = ttk.Scrollbar(list_frame, orient=tk.VERTICAL)
        listbox = tk.Listbox(
            list_frame,
            height=height,
            yscrollcommand=scrollbar.set,
            exportselection=False,
        )
        scrollbar.config(command=listbox.yview)
        listbox.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.LEFT, fill=tk.Y)

        detail = None
        # Hide help for SEL_ARG as requested
        if help_category == "SEL_ARG":
            help_items = []
        else:
            help_items = self.get_help_items(help_category) if help_category else []

        if help_items:
            detail = scrolledtext.ScrolledText(list_frame, wrap=tk.WORD, width=50)
            detail.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=(8, 0))

        def describe(sel):
            if not detail:
                return
            info = ""
            for item in help_items:
                if item["name"].startswith(sel):
                    info = item["info"]
                    break
            detail.config(state="normal")
            detail.delete("1.0", tk.END)
            detail.insert("1.0", info or sel)
            detail.config(state="disabled")

        # Helper to check job bitmask
        def can_equip(job_name, item_jobs_mask):
            if job_name == "All" or not item_jobs_mask:
                return True
            # Map job name to ID (1-based index usually matching bit position)
            # WAR=1, MNK=2, etc. bit 0 is usually unused or ALL?
            # Actually, bit 0 = WAR, bit 1 = MNK? Or 1-based?
            # Let's use the xi.job enum values if available, or a standard mapping.
            # Standard: WAR=1 (1<<0), MNK=2 (1<<1), etc.
            job_id = JOBS.get(job_name, 0)
            if job_id > 0:
                return (item_jobs_mask & (1 << (job_id - 1))) != 0
            return True

        def refresh(filter_text=""):
            listbox.delete(0, tk.END)
            selected_job = local_job_var.get() if filter_by_job else "All"
            selected_magic_type = (
                local_magic_type_var.get()
                if selector_var and selector_var.get() == "Magic"
                else "All"
            )

            filtered = []
            for v in values:
                # Job filtering logic
                if filter_by_job and selected_job != "All":
                    try:
                        # Extract item ID from string (e.g. "Item Name (iLv119) [12345]")
                        item_id_match = re.search(r"\[(\d+)\]$", v)
                        if item_id_match:
                            item_id = int(item_id_match.group(1))
                            equip = ITEM_EQUIPMENT.get(item_id)
                            if equip:
                                if not can_equip(selected_job, equip.get("jobs", 0)):
                                    continue
                        else:
                            # Try to filter JAs/WSs if they are constants
                            if v.startswith("xi.ja."):
                                if hasattr(self, "ja_job_map"):
                                    req_job = self.ja_job_map.get(v)
                                    # req_job is a single job ID from abilities.sql
                                    if req_job and req_job > 0:
                                        sel_job_id = JOBS.get(selected_job, 0)
                                        # 0 means All/None, so if selected_job is valid
                                        if sel_job_id > 0:
                                            # Some abilities might be shared? In SQL it looks like single job column.
                                            # But wait, some abilities are general?
                                            # If req_job is the job ID, we check equality.
                                            if sel_job_id != req_job:
                                                continue
                            elif v.startswith("xi.ws."):
                                if hasattr(self, "ws_job_map"):
                                    allowed_jobs = self.ws_job_map.get(v, [])
                                    if allowed_jobs:
                                        sel_job_id = JOBS.get(selected_job, 0)
                                        if (
                                            sel_job_id > 0
                                            and sel_job_id not in allowed_jobs
                                        ):
                                            continue
                    except Exception:
                        pass

                # Magic Type filtering
                if selected_magic_type != "All" and v.startswith("xi.magic.spell."):
                    if hasattr(self, "spell_type_map"):
                        s_type = self.spell_type_map.get(v)
                        # Map SQL magic type to our dropdown values
                        # SQL magic types: 1=White, 2=Black, 3=Summon, 4=Ninja, 5=Bard, 6=Blue, 7=Geo?
                        # Need to verify these values.
                        # Let's assume I'll map them correctly in load_sql_data.
                        if s_type:
                            if selected_magic_type == "WhiteMagic" and s_type != 1:
                                continue
                            if selected_magic_type == "BlackMagic" and s_type != 2:
                                continue
                            if selected_magic_type == "Summoner" and s_type != 3:
                                continue
                            if selected_magic_type == "Ninjutsu" and s_type != 4:
                                continue
                            if selected_magic_type == "Bard" and s_type != 5:
                                continue
                            if selected_magic_type == "BlueMagic" and s_type != 6:
                                continue
                            if selected_magic_type == "Geomancy" and s_type != 7:
                                continue  # Check this ID

                # Weapon filtering logic
                selected_weapon = local_weapon_var.get()
                if filter_by_weapon and selected_weapon != "All":
                    try:
                        item_id_match = re.search(r"\[(\d+)\]$", v)
                        if item_id_match:
                            item_id = int(item_id_match.group(1))
                            weapon = ITEM_WEAPONS.get(item_id)
                            if weapon:
                                skill_id = weapon.get("skill", 0)
                                skill_name = SKILL_ID_TO_NAME.get(skill_id, "NONE")
                                if skill_name != selected_weapon:
                                    continue
                            else:
                                # Not a weapon, exclude if filtering by weapon type?
                                # Or keep if it's "All"? But we are not "All".
                                # If filtering by "Sword", non-weapons should probably be hidden.
                                continue
                        else:
                            pass
                    except Exception as e:
                        pass

                if filter_text.lower() in v.lower():
                    filtered.append(v)
            listbox._items = filtered
            for item in filtered:
                listbox.insert(tk.END, item)
            if filtered:
                listbox.selection_set(0)
                describe(filtered[0])

        def choose(event=None):
            if listbox.curselection():
                sel = listbox.get(tk.ACTIVE)
                if is_text_widget:
                    # For Text widgets, clear and insert the value
                    target_var.delete("1.0", tk.END)
                    target_var.insert("1.0", sel)
                else:
                    # For StringVar, use set()
                    target_var.set(sel)
            dialog.destroy()

        def on_select(event=None):
            if listbox.curselection():
                sel = listbox.get(tk.ACTIVE)
                describe(sel)

        ttk.Button(dialog, text="Select", command=choose).pack(pady=(0, 8))
        listbox.bind("<Double-Button-1>", choose)
        listbox.bind("<<ListboxSelect>>", on_select)
        search_var.trace_add("write", lambda *args: refresh(search_var.get()))
        if filter_by_job:
            local_job_var.trace_add("write", lambda *args: refresh(search_var.get()))
        if filter_by_weapon:
            local_weapon_var.trace_add("write", lambda *args: refresh(search_var.get()))

        refresh()
        search_entry.focus_set()

    def create_list_picker(
        self,
        parent,
        values,
        textvariable=None,
        width=20,
        title="Pick Item",
        help_category=None,
        job_var=None,
        filter_by_job=False,
        filter_by_weapon=False,
        selector_var=None,
    ):
        frame = ttk.Frame(parent)
        if textvariable is None:
            textvariable = tk.StringVar()
        entry = ttk.Entry(frame, textvariable=textvariable, width=width)
        entry.pack(side=tk.LEFT, fill=tk.X, expand=True)

        btn = ttk.Button(
            frame,
            text="...",
            width=1,
            command=lambda: self.open_filter_list_dialog(
                values,
                textvariable,
                title=title,
                help_category=help_category,
                job_var=job_var,
                filter_by_job=filter_by_job,
                filter_by_weapon=filter_by_weapon,
                selector_var=selector_var,
            ),
        )
        btn.pack(side=tk.LEFT)
        return frame, textvariable

    def create_gear_rows(self, parent):
        """Create gear selection rows for all equipment slots, organized in a single column."""
        all_slots = [
            "main",
            "sub",
            "ranged",
            "ammo",
            "head",
            "neck",
            "ear1",
            "ear2",
            "body",
            "hands",
            "ring1",
            "ring2",
            "back",
            "waist",
            "legs",
            "feet",
        ]

        # Create a single frame for all slots
        gear_frame = ttk.Frame(parent)
        gear_frame.grid(row=1, column=0, sticky="nw", padx=5)

        def add_slot_row(frame, slot, row_num):
            slot_label = (
                slot.upper().replace("1", " 1").replace("2", " 2")
            )  # "EAR1" -> "EAR 1"
            ttk.Label(frame, text=slot_label + ":", width=6).grid(
                row=row_num, column=0, padx=2, pady=2, sticky="w"
            )
            id_var = tk.StringVar()
            name_var = tk.StringVar()

            entry = ttk.Entry(frame, textvariable=id_var, width=6)
            entry.grid(row=row_num, column=1, padx=2, pady=2, sticky="w")

            # Bind id_var changes to update name and trigger stats refresh
            id_var.trace_add(
                "write",
                lambda *args, iv=id_var, nv=name_var, s=slot: self.on_gear_id_changed(
                    iv, nv, s
                ),
            )

            name_label = ttk.Label(
                frame, textvariable=name_var, width=20, relief="sunken", anchor="w"
            )
            name_label.grid(row=row_num, column=2, padx=2, pady=2, sticky="w")

            # Determine if this is a weapon slot for filtering
            is_weapon_slot = slot in ["main", "sub", "ranged"]

            tk.Button(
                frame,
                text="🔍",
                width=1,
                height=1,
                padx=0,
                pady=0,
                borderwidth=0,
                highlightthickness=0,
                command=lambda s=slot, iv=id_var, nv=name_var, iws=is_weapon_slot: self.pick_gear_item(
                    s, iv, nv, filter_by_weapon=iws
                ),
            ).grid(row=row_num, column=3, padx=2, pady=2)

            self.gear_rows.append(
                {"slot": slot, "id_var": id_var, "name_var": name_var}
            )

        # Add all slots in a single column
        for i, slot in enumerate(all_slots):
            add_slot_row(gear_frame, slot, i)

    def on_gear_id_changed(self, id_var, name_var, slot):
        """Called when a gear ID is manually changed - update name and stats."""
        item_id_str = id_var.get().strip()
        if item_id_str:
            try:
                item_id = int(item_id_str)
                name = ITEM_NAMES.get(item_id, f"Unknown ({item_id})")
                # Find display name from slot lists if available
                slot_items = get_slot_item_lists().get(slot, [])
                for item in slot_items:
                    if item["id"] == item_id:
                        name_var.set(item["display"])
                        break
                else:
                    name_var.set(f"{name} [{item_id}]")
            except ValueError:
                pass
        else:
            name_var.set("")

        # Refresh stats preview if it exists
        if hasattr(self, "refresh_stats_preview"):
            self.refresh_stats_preview()

    def pick_gear_item(self, slot, id_var, name_var, filter_by_weapon=False):
        """Open a dialog to pick gear from slot-filtered item list."""
        dialog = tk.Toplevel(self)
        dialog.title(f"Select {slot.upper()}")
        dialog.geometry("550x500")
        dialog.transient(self)
        dialog.grab_set()

        # Position at mouse cursor
        x = self.winfo_pointerx()
        y = self.winfo_pointery()
        dialog.geometry(f"+{x}+{y}")

        # Close on Esc
        dialog.bind("<Escape>", lambda e: dialog.destroy())

        # Get slot-specific items (lazy loaded)
        slot_items = get_slot_item_lists().get(slot, [])
        # Convert to display strings for the listbox
        display_items = [item["display"] for item in slot_items]

        search_var = tk.StringVar()
        ttk.Label(dialog, text="Filter:").pack(anchor="w", padx=8, pady=(8, 2))
        search_entry = ttk.Entry(dialog, textvariable=search_var)
        search_entry.pack(fill=tk.X, padx=8)

        # Job Filter (Optional)
        job_filter_frame = ttk.Frame(dialog)
        job_filter_frame.pack(fill=tk.X, padx=8, pady=(8, 0))
        ttk.Label(job_filter_frame, text="Job:").pack(side=tk.LEFT)
        jobs = ["All"] + sorted(list(JOB_TEMPLATES.keys()))
        job_combo = ttk.Combobox(
            job_filter_frame,
            textvariable=self.main_job_var,
            values=jobs,
            state="readonly",
            width=10,
        )
        job_combo.pack(side=tk.LEFT, padx=5)

        # Weapon Filter (Optional)
        weapon_filter_var = tk.StringVar(value="All")
        if filter_by_weapon:
            ttk.Label(job_filter_frame, text="Weapon:").pack(side=tk.LEFT, padx=(10, 0))
            weapon_skills = [
                k for k, v in SKILLS.items() if (1 <= v <= 12) or (25 <= v <= 26)
            ]
            weapon_skills = ["All"] + sorted(weapon_skills)
            weapon_combo = ttk.Combobox(
                job_filter_frame,
                textvariable=weapon_filter_var,
                values=weapon_skills,
                state="readonly",
                width=15,
            )
            weapon_combo.pack(side=tk.LEFT, padx=5)

        # Info label
        ttk.Label(
            dialog,
            text=f"Found {len(slot_items)} items for {slot.upper()} slot",
            foreground="#666",
        ).pack(anchor="w", padx=8, pady=(2, 4))

        list_frame = ttk.Frame(dialog)
        list_frame.pack(fill=tk.BOTH, expand=True, padx=8, pady=4)

        scrollbar = ttk.Scrollbar(list_frame, orient=tk.VERTICAL)
        listbox = tk.Listbox(
            list_frame, yscrollcommand=scrollbar.set, exportselection=False
        )
        scrollbar.config(command=listbox.yview)
        listbox.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

        # Item details panel
        detail_frame = ttk.LabelFrame(dialog, text="Item Details")
        detail_frame.pack(fill=tk.X, padx=8, pady=4)
        detail_text = scrolledtext.ScrolledText(detail_frame, wrap=tk.WORD, height=6)
        detail_text.pack(fill=tk.BOTH, expand=True, padx=4, pady=4)

        def show_item_details(item_id):
            """Show mods and weapon stats for selected item."""
            detail_text.config(state="normal")
            detail_text.delete("1.0", tk.END)

            lines = [f"Item ID: {item_id}"]
            name = ITEM_NAMES.get(item_id, "Unknown")
            lines.append(f"Name: {name}")

            # Show weapon stats if applicable
            if item_id in ITEM_WEAPONS:
                w = ITEM_WEAPONS[item_id]
                lines.append(f"Weapon DMG: {w.get('dmg', 0)}")
                lines.append(f"Weapon Delay: {w.get('delay', 0)}")
                skill_id = w.get("skill", 0)
                skill_name = SKILL_ID_TO_NAME.get(skill_id, "NONE")
                lines.append(f"Weapon Skill: {skill_name}")

            # Show mods
            if item_id in ITEM_MODS:
                lines.append("\nModifiers:")
                for mod_id, val in ITEM_MODS[item_id]:
                    mod_name = MOD_ID_TO_NAME.get(mod_id, f"MOD_{mod_id}")
                    lines.append(f"  {mod_name}: {val:+d}")

            detail_text.insert("1.0", "\n".join(lines))
            detail_text.config(state="disabled")

        def refresh():
            term = search_var.get().lower()
            listbox.delete(0, tk.END)
            filtered = []

            # Apply job filter if a main job is selected
            selected_main_job = self.main_job_var.get()
            selected_weapon_filter = (
                weapon_filter_var.get() if filter_by_weapon else "All"
            )

            for item in slot_items:
                # Job filtering
                if selected_main_job != "All":
                    if not self.can_equip(
                        selected_main_job,
                        ITEM_EQUIPMENT.get(item["id"], {}).get("jobs", 0),
                    ):
                        continue
                # Weapon filtering
                if filter_by_weapon and selected_weapon_filter != "All":
                    weapon_data = ITEM_WEAPONS.get(item["id"])
                    # print(f"DEBUG: Item {item['id']} ({item['name']}) - Weapon Data: {weapon_data}")
                    if weapon_data:
                        skill_id = weapon_data.get("skill", 0)
                        skill_name = SKILL_ID_TO_NAME.get(skill_id, "NONE")
                        # print(f"DEBUG: Skill ID: {skill_id}, Name: {skill_name}, Filter: {selected_weapon_filter}")
                        if skill_name != selected_weapon_filter:
                            continue
                    else:  # If it's not a weapon, and we're filtering by weapon type, exclude it
                        continue

                # Text filtering
                if term in item["display"].lower() or term in item["name"].lower():
                    filtered.append(item)

            listbox._items = filtered
            for item in filtered:
                listbox.insert(tk.END, item["display"])
            if filtered:
                listbox.selection_set(0)
                show_item_details(filtered[0]["id"])

        refresh()

        def on_select(event=None):
            if listbox.curselection():
                idx = listbox.curselection()[0]
                items = getattr(listbox, "_items", [])
                if idx < len(items):
                    show_item_details(items[idx]["id"])

        def choose(event=None):
            if not listbox.curselection():
                return
            idx = listbox.curselection()[0]
            items = getattr(listbox, "_items", [])
            if idx < len(items):
                selected = items[idx]
                id_var.set(str(selected["id"]))
                name_var.set(selected["display"])
            dialog.destroy()

        btn_frame = ttk.Frame(dialog)
        btn_frame.pack(fill=tk.X, padx=8, pady=(0, 8))
        ttk.Button(btn_frame, text="Select", command=choose).pack(side=tk.LEFT, padx=4)
        ttk.Button(
            btn_frame,
            text="Clear",
            command=lambda: (id_var.set(""), name_var.set(""), dialog.destroy()),
        ).pack(side=tk.LEFT, padx=4)
        ttk.Button(btn_frame, text="Cancel", command=dialog.destroy).pack(
            side=tk.RIGHT, padx=4
        )

        listbox.bind("<Double-Button-1>", choose)
        listbox.bind("<<ListboxSelect>>", on_select)
        search_var.trace_add("write", lambda *args: refresh())
        self.main_job_var.trace_add(
            "write", lambda *args: refresh()
        )  # Trigger refresh when main job changes
        if filter_by_weapon:
            weapon_filter_var.trace_add(
                "write", lambda *args: refresh()
            )  # Trigger refresh when weapon filter changes
        search_entry.focus_set()

    def save_gear_set(self):
        """Save the current gear configuration as a named gear set."""
        # Create gear sets directory if it doesn't exist
        gear_sets_dir = os.path.join(USERDATA_DIR, "gear_sets")
        if not os.path.exists(gear_sets_dir):
            os.makedirs(gear_sets_dir)
        
        # Collect current gear
        current_gear = {}
        has_gear = False
        for row in self.gear_rows:
            if row["id_var"].get():
                try:
                    item_id = int(row["id_var"].get())
                    current_gear[row["slot"]] = {
                        "item_id": item_id,
                        "name": ITEM_NAMES.get(item_id, "Unknown")
                    }
                    has_gear = True
                except ValueError:
                    pass
        
        if not has_gear:
            messagebox.showwarning("No Gear", "No gear is currently equipped to save.")
            return
        
        # Ask for gear set name
        dialog = tk.Toplevel(self)
        dialog.title("Save Gear Set")
        dialog.geometry("400x150")
        dialog.transient(self)
        dialog.grab_set()
        
        ttk.Label(dialog, text="Enter a name for this gear set:", font=("TkDefaultFont", 10, "bold")).pack(pady=(10, 5))
        
        name_var = tk.StringVar()
        name_entry = ttk.Entry(dialog, textvariable=name_var, width=40)
        name_entry.pack(pady=5, padx=20)
        name_entry.focus_set()
        
        # Load existing gear sets to show
        existing_sets = []
        if os.path.exists(gear_sets_dir):
            for file in os.listdir(gear_sets_dir):
                if file.endswith(".json"):
                    existing_sets.append(file.replace(".json", ""))
        
        if existing_sets:
            ttk.Label(dialog, text=f"Existing sets: {', '.join(existing_sets)}", foreground="#666").pack(pady=5)
        
        def do_save():
            name = name_var.get().strip()
            if not name:
                messagebox.showwarning("Invalid Name", "Please enter a name for the gear set.")
                return
            
            # Sanitize filename
            safe_name = re.sub(r'[^a-zA-Z0-9_-]', '_', name)
            gear_set_path = os.path.join(gear_sets_dir, f"{safe_name}.json")
            
            # Check if exists
            if os.path.exists(gear_set_path):
                if not messagebox.askyesno("Overwrite?", f"Gear set '{name}' already exists. Overwrite?"):
                    return
            
            # Save gear set
            try:
                with open(gear_set_path, "w") as f:
                    json.dump({
                        "name": name,
                        "gear": current_gear
                    }, f, indent=4)
                
                messagebox.showinfo("Success", f"Gear set '{name}' saved successfully!")
                dialog.destroy()
            except Exception as e:
                messagebox.showerror("Error", f"Failed to save gear set: {e}")
        
        button_frame = ttk.Frame(dialog)
        button_frame.pack(pady=10)
        
        ttk.Button(button_frame, text="Save", command=do_save).pack(side=tk.LEFT, padx=5)
        ttk.Button(button_frame, text="Cancel", command=dialog.destroy).pack(side=tk.LEFT, padx=5)
        
        name_entry.bind("<Return>", lambda e: do_save())

    def load_gear_set(self):
        """Load a saved gear set."""
        gear_sets_dir = os.path.join(USERDATA_DIR, "gear_sets")
        
        if not os.path.exists(gear_sets_dir):
            messagebox.showinfo("No Gear Sets", "No saved gear sets found.")
            return
        
        # Load all gear sets
        gear_sets = []
        for file in sorted(os.listdir(gear_sets_dir)):
            if file.endswith(".json"):
                try:
                    with open(os.path.join(gear_sets_dir, file), "r") as f:
                        data = json.load(f)
                        gear_sets.append({
                            "filename": file,
                            "name": data.get("name", file.replace(".json", "")),
                            "gear": data.get("gear", {})
                        })
                except Exception:
                    pass
        
        if not gear_sets:
            messagebox.showinfo("No Gear Sets", "No valid gear sets found.")
            return
        
        # Create selection dialog
        dialog = tk.Toplevel(self)
        dialog.title("Load Gear Set")
        dialog.geometry("600x450")
        dialog.transient(self)
        dialog.grab_set()
        
        ttk.Label(dialog, text="Select a gear set to load:", font=("TkDefaultFont", 11, "bold")).pack(pady=10)
        
        # List of gear sets
        list_frame = ttk.Frame(dialog)
        list_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)
        
        listbox = tk.Listbox(list_frame, exportselection=False)
        listbox.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        
        scrollbar = ttk.Scrollbar(list_frame, orient=tk.VERTICAL, command=listbox.yview)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        listbox.configure(yscrollcommand=scrollbar.set)
        
        for gear_set in gear_sets:
            listbox.insert(tk.END, gear_set["name"])
        
        # Preview frame
        preview_frame = ttk.LabelFrame(dialog, text="Gear Set Preview", padding=5)
        preview_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)
        
        preview_text = scrolledtext.ScrolledText(preview_frame, wrap=tk.WORD, height=8)
        preview_text.pack(fill=tk.BOTH, expand=True)
        preview_text.config(state="disabled")
        
        def on_select(event=None):
            if not listbox.curselection():
                return
            
            selected_idx = listbox.curselection()[0]
            gear_set = gear_sets[selected_idx]
            
            # Display gear preview
            preview_lines = []
            for slot in ALL_EQUIP_SLOTS:
                if slot in gear_set["gear"]:
                    item = gear_set["gear"][slot]
                    preview_lines.append(f"{slot.upper()}: {item['name']} ({item['item_id']})")
            
            preview_text.config(state="normal")
            preview_text.delete("1.0", tk.END)
            if preview_lines:
                preview_text.insert("1.0", "\n".join(preview_lines))
            else:
                preview_text.insert("1.0", "(Empty gear set)")
            preview_text.config(state="disabled")
        
        listbox.bind("<<ListboxSelect>>", on_select)
        
        # Buttons
        button_frame = ttk.Frame(dialog)
        button_frame.pack(pady=10)
        
        def do_load():
            if not listbox.curselection():
                messagebox.showwarning("No Selection", "Please select a gear set to load.")
                return
            
            selected_idx = listbox.curselection()[0]
            gear_set = gear_sets[selected_idx]
            
            # Clear current gear
            for row in self.gear_rows:
                row["id_var"].set("")
                row["name_var"].set("")
            
            # Load gear from set
            for slot, item_data in gear_set["gear"].items():
                for row in self.gear_rows:
                    if row["slot"] == slot:
                        row["id_var"].set(str(item_data["item_id"]))
                        # Name will be updated by the trace callback
                        break
            
            # Refresh stats
            if hasattr(self, "refresh_stats_preview"):
                self.refresh_stats_preview()
            
            messagebox.showinfo("Success", f"Gear set '{gear_set['name']}' loaded successfully!")
            dialog.destroy()
        
        def do_delete():
            if not listbox.curselection():
                messagebox.showwarning("No Selection", "Please select a gear set to delete.")
                return
            
            selected_idx = listbox.curselection()[0]
            gear_set = gear_sets[selected_idx]
            
            if not messagebox.askyesno("Confirm Delete", f"Delete gear set '{gear_set['name']}'?"):
                return
            
            try:
                os.remove(os.path.join(gear_sets_dir, gear_set["filename"]))
                messagebox.showinfo("Deleted", f"Gear set '{gear_set['name']}' deleted.")
                dialog.destroy()
                # Reopen dialog with updated list
                self.load_gear_set()
            except Exception as e:
                messagebox.showerror("Error", f"Failed to delete gear set: {e}")
        
        ttk.Button(button_frame, text="Load", command=do_load).pack(side=tk.LEFT, padx=5)
        ttk.Button(button_frame, text="Delete", command=do_delete).pack(side=tk.LEFT, padx=5)
        ttk.Button(button_frame, text="Cancel", command=dialog.destroy).pack(side=tk.LEFT, padx=5)
        
        if gear_sets:
            listbox.selection_set(0)
            on_select()

    def get_trust_files(self):
        files = []
        for f in os.listdir(CURRENT_DIR):
            if f.endswith(".lua") and f != os.path.basename(__file__):
                # Check if placeholder
                path = os.path.join(CURRENT_DIR, f)
                is_placeholder = False
                try:
                    with open(path, "r", encoding="utf-8") as file:
                        content = file.read()
                        # Heuristic: if file is small or has no gambits/listeners defined in t_editor blocks
                        # Or maybe just check if it has "t_editor" blocks at all?
                        # If it has no t_editor blocks, it might be a raw file or empty.
                        # If it has t_editor blocks but they are empty?
                        # Let's check for "gambits = {" or "listeners = {" inside t_editor blocks?
                        # Or simpler: if file size < 2KB?
                        # Or if it doesn't contain "mob:addGambit"?
                        if (
                            "mob:addGambit" not in content
                            and "mob:addListener" not in content
                        ):
                            is_placeholder = True
                except:
                    pass

                if is_placeholder:
                    files.append("* " + f)
                else:
                    files.append(f)

        # Sort: Placeholders (* ...) first, then others. Both groups alphabetically.
        files.sort(key=lambda x: (not x.startswith("* "), x))
        return files

