    def create_stats_preview(self, parent):
        """Create the stats preview panel showing combined base + gear stats."""
        # Header
        ttk.Label(
            parent, text="Base stats for Lv99 trust + gear mods:", foreground="#666"
        ).pack(anchor="w", pady=(0, 5))

        # Refresh button
        ttk.Button(
            parent, text="↻ Refresh Stats", command=self.refresh_stats_preview
        ).pack(anchor="w", pady=(0, 5))

        # Stats display frame
        self.stats_display_frame = ttk.Frame(parent)
        self.stats_display_frame.pack(fill=tk.BOTH, expand=True)

        # Create stat labels
        self.stat_labels = {}
        stat_groups = [
            ("HP/MP", ["HP", "MP"]),
            ("Primary Stats", ["STR", "DEX", "VIT", "AGI", "INT", "MND", "CHR"]),
            ("Physical", ["ATT", "ACC", "DEF", "EVA"]),
            ("Magical", ["MATT", "MACC", "MDEF", "MEVA"]),
        ]

        row = 0
        for group_name, stats in stat_groups:
            ttk.Label(
                self.stats_display_frame,
                text=group_name + ":",
                font=("TkDefaultFont", 9, "bold"),
            ).grid(row=row, column=0, columnspan=4, sticky="w", pady=(8, 2))
            row += 1

            col = 0
            for stat in stats:
                ttk.Label(self.stats_display_frame, text=stat + ":", width=6).grid(
                    row=row, column=col, sticky="w", padx=2
                )
                val_label = ttk.Label(
                    self.stats_display_frame,
                    text="0",
                    width=8,
                    relief="sunken",
                    anchor="w",
                )
                val_label.grid(row=row, column=col + 1, sticky="w", padx=2)
                self.stat_labels[stat] = val_label
                col += 2
                if col >= 4:
                    col = 0
                    row += 1
            if col > 0:
                row += 1

        # Gear mods summary
        ttk.Label(
            self.stats_display_frame,
            text="Gear Mods:",
            font=("TkDefaultFont", 9, "bold"),
        ).grid(row=row, column=0, columnspan=4, sticky="w", pady=(8, 2))
        row += 1

        self.gear_mods_text = scrolledtext.ScrolledText(
            self.stats_display_frame, wrap=tk.WORD, height=8, width=30
        )
        self.gear_mods_text.grid(row=row, column=0, columnspan=4, sticky="nsew", pady=2)

        # Initialize stats
        self.refresh_stats_preview()

    def refresh_stats_preview(self):
        """Calculate and display combined stats from base + gear mods."""
        # Start with base stats
        base_stats = dict(BASE_STATS_LV99)
        gear_stats = {}

        # Map mod names to stat names for display
        mod_to_stat = {
            "HP": "HP",
            "MP": "MP",
            "STR": "STR",
            "DEX": "DEX",
            "VIT": "VIT",
            "AGI": "AGI",
            "INT": "INT",
            "MND": "MND",
            "CHR": "CHR",
            "ATT": "ATT",
            "ACC": "ACC",
            "DEF": "DEF",
            "EVA": "EVA",
            "MATT": "MATT",
            "MACC": "MACC",
            "MDEF": "MDEF",
            "MEVA": "MEVA",
            # Alt names from mod.lua
            "MAIN_DMG_RATING": "ATT",
        }

        # Initialize gear stats
        for k in base_stats:
            gear_stats[k] = 0

        gear_mods_summary = []

        # Collect mods from equipped gear
        for row in self.gear_rows:
            item_id_str = row["id_var"].get().strip()
            if not item_id_str:
                continue
            try:
                item_id = int(item_id_str)
            except ValueError:
                continue

            slot = row["slot"]
            item_name = ITEM_NAMES.get(item_id, f"Item {item_id}")

            # Get item mods
            if item_id in ITEM_MODS:
                slot_mods = []
                for mod_id, val in ITEM_MODS[item_id]:
                    mod_name = MOD_ID_TO_NAME.get(mod_id, f"MOD_{mod_id}")
                    slot_mods.append(f"{mod_name}: {val:+d}")

                    # Apply to stats if mappable
                    if mod_name in mod_to_stat:
                        stat_key = mod_to_stat[mod_name]
                        if stat_key in gear_stats:
                            gear_stats[stat_key] += val

                if slot_mods:
                    gear_mods_summary.append(f"[{slot.upper()}] {item_name}:")
                    for m in slot_mods:
                        gear_mods_summary.append(f"  {m}")

            # Get weapon stats - display separately from armor mods
            if item_id in ITEM_WEAPONS and slot in ["main", "sub", "ranged"]:
                w = ITEM_WEAPONS[item_id]
                dmg = w.get("dmg", 0)
                delay = w.get("delay", 0)

                if slot == "main":
                    gear_mods_summary.append(
                        f"[{slot.upper()}] {item_name}: DMG:{dmg} Delay:{delay}"
                    )
                    # WEAPON_BONUS is not a stat in base_stats, but we can track it if we want
                    # For now, just showing it in summary is enough
                else:
                    gear_mods_summary.append(
                        f"[{slot.upper()}] {item_name}: DMG:{dmg} Delay:{delay}"
                    )

        # Also add manual mods from the Mods tab
        if hasattr(self, "mod_rows"):
            manual_mods = []
            for _, mod_var, val_entry, _, _ in self.mod_rows:
                mod_name = mod_var.get()
                if mod_name:
                    try:
                        val = int(val_entry.get())
                        manual_mods.append(f"{mod_name}: {val:+d}")
                        if mod_name in mod_to_stat:
                            stat_key = mod_to_stat[mod_name]
                            if stat_key in gear_stats:
                                gear_stats[stat_key] += val
                    except ValueError:
                        pass

            if manual_mods:
                gear_mods_summary.append("\n[MANUAL MODS]:")
                for m in manual_mods:
                    gear_mods_summary.append(f"  {m}")

        # Update stat labels
        for stat, label in self.stat_labels.items():
            base = base_stats.get(stat, 0)
            gear = gear_stats.get(stat, 0)

            if gear != 0:
                text = f"{base}+{gear}"
            else:
                text = f"{base}"

            label.config(text=text, foreground="")

        # Update gear mods text
        self.gear_mods_text.config(state="normal")
        self.gear_mods_text.delete("1.0", tk.END)
        if gear_mods_summary:
            self.gear_mods_text.insert("1.0", "\n".join(gear_mods_summary))
        else:
            self.gear_mods_text.insert("1.0", "(No gear equipped)")
        self.gear_mods_text.config(state="disabled")

