    def build_listener_template(self, event_name, template_key=None):
        signature = LISTENER_SIGNATURES.get(event_name, "function(mobArg, ...)")
        lines = [
            f"-- {event_name}",
            f"-- {LISTENER_HELP.get(event_name, '').strip()}",
            f"return {signature}",
            "{",
        ]
        chosen_data = LISTENER_TEMPLATES.get(template_key or "", {})
        # If template_key is provided but not found, or if it's empty, fallback to LOG_EVENT
        if not chosen_data and not template_key:
            chosen_data = LISTENER_TEMPLATES.get("LOG_EVENT", {})

        # Handle new dict structure or old list structure (backward compat if needed, though we replaced all)
        if isinstance(chosen_data, dict):
            chosen_body = chosen_data.get("body", [])
        else:
            chosen_body = chosen_data  # Should be list

        lines.extend([f"    {l}" for l in chosen_body])
        lines.append("}")
        return "\n".join(lines)

    def listener_event_changed(self, row_data):
        ev = row_data["event_var"].get()
        if ev:
            # Only update tag if it's empty or matches previous auto-tag
            current_tag = row_data["tag_entry"].get()
            prev_auto = row_data.get("auto_tag", "")
            if not current_tag or current_tag == prev_auto:
                new_auto_tag = f"{ev}_L{row_data.get('id', 0)}"
                row_data["tag_entry"].delete(0, tk.END)
                row_data["tag_entry"].insert(0, new_auto_tag)
                row_data["auto_tag"] = new_auto_tag

        # Only insert template if body is empty
        if ev and not row_data["body_text"].get("1.0", tk.END).strip():
            # Default template for event? We don't have per-event defaults, just generic LOG_EVENT
            # So maybe just leave it empty or insert a basic skeleton?
            # For now, let's not force a template on event change unless user picks one.
            # But the previous code did:
            # row_data["body_text"].insert("1.0", self.build_listener_template(ev))
            # Let's keep it but use a simple default if no key provided
            row_data["body_text"].insert("1.0", self.build_listener_template(ev))

        signature = LISTENER_SIGNATURES.get(ev, "")
        help_line = LISTENER_HELP.get(ev, "")
        row_data["signature_label"].configure(text=f"{signature}  {help_line}")

    def add_listener_row(self, event_name="", tag="", body=""):
        row_frame = ttk.Frame(self.listeners_scrollable_frame)
        row_frame.pack(fill=tk.X, pady=4, anchor="w")

        ttk.Label(row_frame, text="Event:").pack(side=tk.LEFT)
        event_frame, event_var = self.create_list_picker(
            row_frame,
            LISTENER_EVENTS,
            width=14,
            textvariable=tk.StringVar(),
            title="Pick Listener Event",
            help_category="LISTENER_EVENT",
        )
        event_var.set(event_name)
        event_frame.pack(side=tk.LEFT, padx=4)

        ttk.Label(row_frame, text="Tag:").pack(side=tk.LEFT)
        tag_entry = ttk.Entry(row_frame, width=12)
        tag_entry.insert(0, tag)
        tag_entry.pack(side=tk.LEFT, padx=4)

        body_frame = ttk.Frame(self.listeners_scrollable_frame)
        body_frame.pack(fill=tk.BOTH, expand=True, padx=4, pady=(0, 6))
        ttk.Label(body_frame, text="Body:").pack(anchor="w")
        body_text = scrolledtext.ScrolledText(body_frame, height=4)
        body_text.insert("1.0", body)
        body_text.pack(fill=tk.BOTH, expand=True)

        sig_label = ttk.Label(body_frame, text="", foreground="#5a5a5a")
        sig_label.pack(anchor="w", pady=(2, 0))

        btn_frame = ttk.Frame(body_frame)
        btn_frame.pack(fill=tk.X, pady=(2, 0))
        ttk.Label(btn_frame, text="Preset:").pack(side=tk.LEFT, padx=(0, 4))
        preset_var = tk.StringVar()
        preset_picker, _ = self.create_list_picker(
            btn_frame,
            list(LISTENER_TEMPLATES.keys()),
            textvariable=preset_var,
            width=12,
            title="Pick Listener Preset",
        )
        preset_picker.pack(side=tk.LEFT, padx=(0, 6))
        ttk.Button(
            btn_frame,
            text="Apply",
            width=6,
            command=lambda ev=event_var, bd=body_text, pv=preset_var, te=tag_entry: self.apply_listener_template(
                ev, bd, te, pv.get()
            ),
        ).pack(side=tk.LEFT)
        ttk.Button(
            btn_frame,
            text="Remove",
            command=lambda: self.remove_listener_row(row_frame, body_frame, row_data),
        ).pack(side=tk.RIGHT)

        row_data = {
            "row_frame": row_frame,
            "event_var": event_var,
            "tag_entry": tag_entry,
            "body_text": body_text,
            "body_frame": body_frame,
            "signature_label": sig_label,
            "auto_tag": "",
            "id": self.listener_row_counter + 1,
        }
        self.listener_row_counter += 1
        event_var.trace_add(
            "write", lambda *args, rd=row_data: self.listener_event_changed(rd)
        )
        self.listener_rows.append(row_data)
        self.listener_event_changed(row_data)

    def apply_listener_template(
        self, event_var, body_text, tag_entry, template_key=None
    ):
        # Get template data
        tpl = LISTENER_TEMPLATES.get(template_key)
        if not tpl:
            return

        # Update Event if present in template
        if "event" in tpl:
            event_var.set(tpl["event"])

        # Update Tag if present (we might want to append ID to make it unique, or just set it)
        # The user can edit it later.
        if "tag" in tpl:
            tag_entry.delete(0, tk.END)
            tag_entry.insert(0, tpl["tag"])

        ev = event_var.get()
        # if not ev: return  -- Removed to allow applying template without event
        body_text.delete("1.0", tk.END)
        body_text.insert("1.0", self.build_listener_template(ev, template_key))

    def remove_listener_row(self, row_frame, body_frame, row_data=None):
        if row_data and row_data in self.listener_rows:
            self.listener_rows.remove(row_data)
        row_frame.destroy()
        body_frame.destroy()

    def remove_effect_row(self, row_frame):
        for i, (frame, _, _, _) in enumerate(self.effect_rows):
            if frame == row_frame:
                self.effect_rows.pop(i)
                break
        row_frame.destroy()

